import makeActionRequest from "cloudflare-worker-action/bootstrap";
export const GET = (...args) => makeActionRequest(args, "/action","GET", (url, init) => {
  const header = new Headers(init?.headers);
  header.set("x-custom-header", "This is a custom header added by the custom fetch function!");
  const modifiedInit = {
    ...init,
    headers: header
  };
  return fetch(url, modifiedInit);
});